# ==============================================================================
# Subclone Enrichment Bar Charts
# ==============================================================================
# Bar charts showing the percentage of subclones with 0, 1, or >1 significantly
# enriched gene sets (HALLMARK and REACTOME, up- and down-regulated separately).
#
# Input: summary_df — output of build_subclone_enrichment_summary()
#   (columns: Cancer_type, Study, Sample, comp, HALLMARK, REACTOME, ...)

plot_suppFig10_subclone_enrichment <- function(summary_df, db = "HALLMARK",
                                               direction_label = "up-regulated") {
  summary_df %>%
    mutate(category = case_when(
      .data[[db]] == 0 ~ "None",
      .data[[db]] == 1 ~ "One sig. pathway",
      .data[[db]] >= 2 ~ "More than one sig. pathway"
    )) %>%
    count(category) %>%
    mutate(
      Percentage = n / sum(n) * 100,
      category   = factor(category,
                          levels = c("None", "One sig. pathway",
                                     "More than one sig. pathway"))
    ) %>%
    ggplot(aes(x = category, y = Percentage)) +
    geom_col(fill = "gray30", alpha = 0.6) +
    geom_text(aes(label = paste0(round(Percentage, 1), "%")),
              nudge_y = 3, size = 5) +
    scale_x_discrete(labels = c(
      "None"                         = "None",
      "One sig. pathway"             = "One\nsig. pathway",
      "More than one sig. pathway"   = "More than one\nsig. pathway"
    )) +
    labs(y = paste0("% of Subclones with\nSignificantly Enriched\n",
                    db, " Gene Sets\n(", direction_label, ")"),
         x = "") +
    graph_theme
}

# ==============================================================================
# Recurrent Aneuploidy Correlation Heatmap
# ==============================================================================
# Heatmap showing whether (chromosome-arm, cancer-type) pairs have a positive,
# negative, or non-significant correlation with TCGA GSEA results.
#
# Input: df_count — data.frame with columns Arm, Type (cancer type),
#        label ("Concordant Direction" / "Discordant Direction" /
#               "Not significant"), Correlation, P_val

plot_correlation_heatmap <- function(df_count, db = "HALLMARK",
                                            cnv_type = "Loss") {
  library(stringr)
  df_count <- df_count %>%
    mutate(
      chr_num  = factor(str_extract(Arm, "^[0-9XY]+"),
                        levels = as.character(1:22)),
      arm_side = str_extract(Arm, "[pq]"),
      arm_order = if_else(arm_side == "p", 1, 2),
      label    = factor(label,
                        levels = c("Concordant Direction",
                                   "Discordant Direction",
                                   "Not significant"))
    ) %>%
    arrange(chr_num, arm_order, Type) %>%
    mutate(Arm = factor(Arm, levels = unique(Arm)))

  corr_colors <- c(
    "Concordant Direction" = "darkgreen",
    "Discordant Direction" = "purple4",
    "Not significant"      = "#cccccc"
  )

  ggplot(df_count, aes(x = Arm, y = Type, fill = label)) +
    geom_tile(color = "white") +
    scale_fill_manual(values = corr_colors) +
    labs(x = "Chromosome Arm",
         y = "Cancer Type",
         fill = paste0(pathways_titles_list[i], " Pathway\nEnrichment")) +
    graph_theme +
    theme(axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1),
          axis.line    = element_blank())
}

# ==============================================================================
# Single-Sample Gene Expression Violin Plot (Neutral vs. CNV)
# ==============================================================================
# Compares the expression of a specific gene between Neutral cells and cells 
# with a specific CNV (Loss/DEL or Gain/AMP) within a single patient sample.
#
# Input: gene_counts — data.frame with 'pred' (NEUTRAL, DEL, or AMP) and a column
#                      named after the target gene containing expression values.
#        gene        — character string of the gene name (e.g., "CDKN2A")
#        cnv_type    — character string, either "Loss" or "Gain"
#        title_text  — character string for the plot title

plot_single_sample_gene_exp <- function(gene_counts, gene, cnv_type, title_text) {
  
  cnv_label <- ifelse(cnv_type == 'Loss', 'DEL', 'AMP')
  cnv_display <- ifelse(cnv_type == 'Loss', 'Loss', 'Gain')
  
  # Ensure factors are set for plotting order
  gene_counts$pred <- factor(gene_counts$pred, levels = c("NEUTRAL", cnv_label))
  
  # Map dynamic labels for the x-axis
  x_labels <- c("NEUTRAL" = "Neutral")
  x_labels[cnv_label] <- cnv_display
  
  ggplot(gene_counts, aes(x = pred, y = get(gene))) +
    geom_violin(trim = FALSE, alpha = 0.6, fill = "gray") +
    geom_boxplot(width = 0.1, fill = 'white', outlier.shape = NA) +
    geom_jitter(alpha = 0.4, size = 1, width = 0.1, height = 0) +  
    stat_compare_means(
      method = "wilcox.test",
      comparisons = list(c("NEUTRAL", cnv_label)),
      label = "p.format",
      size = 5
    ) +
    scale_x_discrete(labels = x_labels) +
    labs(x = "", y = paste0(gene, " Expression")) +
    ggtitle(title_text) +
    graph_theme + 
    theme(axis.title = element_text(size = 15), 
          axis.text.y = element_text(size = 13), 
          plot.title = element_text(face = "plain", size = 17))
}

# ==============================================================================
# Average ssGSEA Enrichment Score (Paired Cross-Sample)
# ==============================================================================
# Compares the average ssGSEA enrichment score for a specific pathway between 
# Neutral and altered (Loss/Gain) cells, paired across multiple samples.
#
# Input: df_long      — paired data.frame containing:
#                       * 'condition': 'NEUTRAL' vs 'DEL' or 'AMP'.
#                       * 'value': average ssGSEA enrichment score 
#                                  calculated for that specific condition.
#        geneset_name — formatted character string for the y-axis label 
#                       (e.g., "SIGNALING_BY_TGF_BETA...")
#        cnv_type     — character string, either "Loss" or "Gain"

plot_avg_ssgsea_enrichment <- function(df_long, geneset_name, cnv_type) {
  
  cnv_label <- ifelse(cnv_type == 'Loss', 'DEL', 'AMP')
  cnv_display <- ifelse(cnv_type == 'Loss', 'Loss', 'Gain')
  
  df_long$condition <- factor(df_long$condition, levels = c('NEUTRAL', cnv_label))
  
  x_labels <- c("NEUTRAL" = "Neutral")
  x_labels[cnv_label] <- cnv_display
  
  ggplot(df_long, aes(x = condition, y = value)) +
    geom_violin(trim = FALSE, alpha = 0.6, fill = "gray") +
    geom_boxplot(width = 0.1, fill = 'white', outlier.shape = NA) +
    geom_jitter(alpha = 0.4, size = 1, width = 0.1, height = 0) +
    stat_compare_means(
      method = "wilcox.test",
      comparisons = list(c("NEUTRAL", cnv_label)),
      paired = TRUE,
      label = "p.format",
      size = 5
    ) +
    scale_x_discrete(labels = x_labels) +
    labs(x = "", y = paste0(geneset_name, "\nAverage ssGSEA Enrichment Score")) +
    graph_theme + 
    theme(axis.title = element_text(size = 15), 
          axis.text.y = element_text(size = 13))
}

